1	// Differential runner: compares the Python executable against a Node entry file.
2	// Usage: node diff.mjs <entry.mjs> [--limit N] [--tag PREFIX] [--stderr] [--out report.json]
3	import { readFileSync, writeFileSync } from 'node:fs';
4	import { spawn } from 'node:child_process';
5	
6	const EXE = '/workspace/dataset/test6_executable';
7	const argv = process.argv.slice(2);
8	const entry = argv[0];
9	if (!entry) { console.error('usage: node diff.mjs <entry.mjs> [opts]'); process.exit(64); }
10	const getOpt = (n, d) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : d; };
11	const limit = Number(getOpt('--limit', '0')) || 0;
12	const tagFilter = getOpt('--tag', '');
13	const cmpStderr = argv.includes('--stderr');
14	const outPath = getOpt('--out', '');
15	const CONC = Number(getOpt('--conc', '48'));
16	
17	let cases = readFileSync('/tmp/dt/corpus.jsonl', 'utf8').trim().split('\n').map((l) => JSON.parse(l));
18	if (tagFilter) cases = cases.filter((c) => c.tag.startsWith(tagFilter));
19	if (limit) cases = cases.slice(0, limit);
20	
21	function run(cmd, args) {
22	  return new Promise((resolve) => {
23	    const p = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
24	    let so = '', se = '';
25	    p.stdout.on('data', (d) => { so += d; });
26	    p.stderr.on('data', (d) => { se += d; });
27	    p.on('error', (e) => resolve({ rc: -1, so: '', se: String(e) }));
28	    p.on('close', (rc) => resolve({ rc, so, se }));
29	  });
30	}
31	
32	// Normalize stderr so PyInstaller PID noise / prog name / file paths don't create false diffs.
33	function normErr(s) {
34	  return s
35	    .replace(/\[PYI-\d+:ERROR\][^\n]*\n?/g, '')
36	    .replace(/test6(_executable|\.py|\.mjs)/g, 'PROG')
37	    .trim();
38	}
39	
40	const mismatches = [];
41	let done = 0, ok = 0;
42	let idx = 0;
43	
44	async function worker() {
45	  while (idx < cases.length) {
46	    const i = idx++;
47	    const c = cases[i];
48	    const [a, b] = await Promise.all([run(EXE, c.argv), run(process.execPath, [entry, ...c.argv])]);
49	    let bad = null;
50	    if (a.so !== b.so) bad = 'stdout';
51	    else if (a.rc !== b.rc) bad = 'rc';
52	    else if (cmpStderr && normErr(a.se) !== normErr(b.se)) bad = 'stderr';
53	    done++;
54	    if (bad) {
55	      mismatches.push({ i, tag: c.tag, argv: c.argv, kind: bad, py: { rc: a.rc, so: a.so, se: normErr(a.se) }, js: { rc: b.rc, so: b.so, se: normErr(b.se) } });
56	    } else ok++;
57	    if (done % 2000 === 0) process.stderr.write(`  ...${done}/${cases.length} (${mismatches.length} bad)\n`);
58	  }
59	}
60	
61	const t0 = process.hrtime.bigint === undefined ? 0 : 0;
62	await Promise.all(Array.from({ length: CONC }, worker));
63	
64	console.log(`total=${cases.length} pass=${ok} fail=${mismatches.length}`);
65	const byTag = {};
66	for (const m of mismatches) byTag[m.tag] = (byTag[m.tag] || 0) + 1;
67	if (mismatches.length) console.log('failures by tag:', JSON.stringify(byTag));
68	for (const m of mismatches.slice(0, 60)) {
69	  console.log(`FAIL[${m.kind}] ${m.tag} argv=${JSON.stringify(m.argv)}\n   py rc=${m.py.rc} out=${JSON.stringify(m.py.so)}${cmpStderr ? ' err=' + JSON.stringify(m.py.se) : ''}\n   js rc=${m.js.rc} out=${JSON.stringify(m.js.so)}${cmpStderr ? ' err=' + JSON.stringify(m.js.se) : ''}`);
70	}
71	if (mismatches.length > 60) console.log(`... and ${mismatches.length - 60} more`);
72	if (outPath) writeFileSync(outPath, JSON.stringify(mismatches, null, 1));
73	process.exit(mismatches.length ? 1 : 0);
74

1	// Corpus generator for differential testing. Deterministic (seeded PRNG).
2	import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
3	
4	let _s = 0x2f6e2b1 >>> 0;
5	function rnd() { // mulberry32
6	  _s = (_s + 0x6D2B79F5) >>> 0;
7	  let t = _s;
8	  t = Math.imul(t ^ (t >>> 15), t | 1);
9	  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
10	  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
11	}
12	const ri = (n) => Math.floor(rnd() * n);
13	const pick = (a) => a[ri(a.length)];
