// batch prober: node probe.mjs <file-with-json-lines-of-argv-arrays>
import { readFileSync } from 'node:fs';
import { spawn } from 'node:child_process';
const EXE = '/workspace/dataset/test6_executable';
const file = process.argv[2];
const alt = process.argv[3]; // optional: node entry to compare
const lines = readFileSync(file, 'utf8').trim().split('\n').filter(Boolean);
const cases = lines.map((l) => JSON.parse(l));
function run(cmd, args) {
  return new Promise((res) => {
    const p = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let so = '', se = '';
    p.stdout.on('data', (d) => so += d);
    p.stderr.on('data', (d) => se += d);
    p.on('error', (e) => res({ rc: -1, so: '', se: String(e) }));
    p.on('close', (rc) => res({ rc, so, se }));
  });
}
const norm = (s) => s.replace(/\[PYI-\d+:ERROR\][^\n]*\n?/g, '').replace(/test6(_executable|\.py|\.mjs)/g, 'PROG').trim();
let i = 0; const out = new Array(cases.length);
async function w() {
  while (i < cases.length) {
    const k = i++;
    const a = await run(EXE, cases[k]);
    let line = `${JSON.stringify(cases[k])} => rc=${a.rc} out=${JSON.stringify(a.so)}`;
    if (a.se) line += ` err=${JSON.stringify(norm(a.se))}`;
    if (alt) {
      const b = await run(process.execPath, [alt, ...cases[k]]);
      const same = a.so === b.so && a.rc === b.rc && norm(a.se) === norm(b.se);
      line = (same ? 'OK   ' : 'DIFF ') + line;
      if (!same) line += `\n      JS: rc=${b.rc} out=${JSON.stringify(b.so)} err=${JSON.stringify(norm(b.se))}`;
    }
    out[k] = line;
  }
}
await Promise.all(Array.from({ length: 16 }, w));
console.log(out.join('\n'));

